import static org.junit.jupiter.api.Assertions.*;import static com.openggf.game.soniccd.objects.CdObjectState.ByteField.*;import static com.openggf.game.soniccd.objects.CdObjectState.WordField.*;import static com.openggf.game.soniccd.objects.CdObjectState.LongField.*;
/** Tests FIRST, ALL Java UNRUN. Original media/Frame/pool/pass with inherited explicitly
 * CONSTRUCTED Core/Ports/primary controls. Never actual World authority or diagnostic hydration. */
class TestSonicCdR31aSpringPass {
 @Test void actualSourceRootsAndCanonicalIncludesUseNoPadding()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){
  assertEquals(0x209298,h.assets.view(CdR31aAssets.Asset.OBJECT_INDEX).unsignedLong(9*4));var a=h.objects.springAssets();assertSame(a,h.objects.springAssets());assertEquals(0x20968A,a.mappingsAddress());assertEquals(199,a.vertical().mappings().length());assertEquals(14,a.vertical().animationTable().length());assertEquals("f1c0f43ac8925447d88d33fed86d98062d4156d7430802e4c0de37ed620753fd",sha(a.vertical().mappings()));assertEquals("7f641336673d1419b30d9555fa0e2ff3a12a95811b26f2d12d96e8b32befb6b5",sha(a.vertical().animationTable()));assertEquals(67,CdR31aAssets.Asset.values().length);}}
 @Test void cleanOffscreenInitReturnsBeforeMainAndPreservesCompleteNonwrites()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){var s=seed(h,32,0,0);var before=h.placement.capture();var core=h.cut;var actor=h.frame.captureActor();var shared=h.frame.captureShared();h.walk();assertEquals(init(s,2,0x520,0x20968A,16,8),h.placement.pool().state(32));assertEquals(core,h.cut);assertEquals(actor,h.frame.captureActor());assertEquals(shared,h.frame.captureShared());nonwrites(h,before,Set.of(32));h.finish();}}
 @Test void dirtyInitRetainsFractionsAliasesAndChoosesActualAllFourDirections()throws Exception{
  for(int subtype:new int[]{0,2,4,6,8,10,12})try(var h=new TestSonicCdR31aObjectPass.Harness()){var s=seed(h,32,0,subtype).moveByte(SUBTYPE2,255).moveWord(X_FRACTION,0xCAFE).moveWord(Y_FRACTION,0xBEEF).moveByte(ROUTINE_2,3).moveWord(SPRING_PARENT,0);h.placement.pool().write(s);h.walk();boolean side=(subtype&4)!=0,diag=!side&&(subtype&8)!=0;int tile=diag?0x4F2:0x520;if((subtype&2)!=0)tile|=0x2000;assertEquals(init(s,side?8:diag?20:2,tile,0x20968A+(side?6:diag?80:0),side?8:diag?24:16,side?16:diag?12:8),h.placement.pool().state(32));h.finish();}}
 @Test void flippedVerticalInitSelectsDownWithoutASecondaryPlayer()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){var s=seed(h,32,0,0).moveByte(SPRITE_FLAGS,2);h.placement.pool().write(s);h.walk();assertEquals(init(s,14,0x520,0x20968A,16,8).moveByte(FLAGS,s.flags()|2),h.placement.pool().state(32));h.finish();}}
 @Test void offscreenUnknownRoutineSkipsTheControlTableButStillUsesRealDrawAndTail()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){var s=seed(h,32,254,0);h.walk();assertEquals(s,h.placement.pool().state(32));h.finish();}}
 @Test void onscreenUnknownRoutineStopsBeforeDrawAndRetiresTheOriginalScope()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){var s=seed(h,32,254,0).moveByte(SPRITE_FLAGS,0x84);h.placement.pool().write(s);var e=assertThrows(CdSpring.UnsupportedSpring.class,h::walk);assertEquals(CdSpring.UnsupportedBoundary.ROUTINE_DISPATCH,e.boundary());assertSame(s,h.placement.pool().state(32));assertNull(field(h.pass,"springInvocation"));}}
 @Test void postDrawReadsTheLiveParentThenAppliesSignedOffsetsWithoutSavedClear()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){seed(h,32,2,0);var s=h.placement.pool().state(32).moveWord(SPRING_PARENT,0xD840).moveByte(SPRING_PARENT_X_OFFSET,0xFE).moveByte(SPRING_PARENT_Y_OFFSET,3);h.placement.pool().write(s);var parent=h.placement.pool().state(33).moveWord(X,200).moveWord(Y,300);h.placement.pool().write(parent);var before=h.placement.capture();h.walk();assertEquals(198,h.placement.pool().state(32).centreX());assertEquals(303,h.placement.pool().state(32).centreY());nonwrites(h,before,Set.of(32));h.finish();}}
 @Test void representedReservedParentUsesActualCoreWordsWithoutAnInactiveActor()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){seed(h,32,2,0);h.edit(5,row->{row[8]=0;row[9]=(byte)201;row[12]=1;row[13]=44;});h.placement.pool().write(h.placement.pool().state(32).moveWord(SPRING_PARENT,0xD140));h.walk();assertEquals(201,h.placement.pool().state(32).centreX());assertEquals(300,h.placement.pool().state(32).centreY());h.finish();}}
 @Test void unalignedParentStopsAtTheFirstXReadAfterActualDrawClear()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){var s=seed(h,32,2,0).moveWord(SPRING_PARENT,0xD801).moveByte(SPRITE_FLAGS,0x04);h.placement.pool().write(s);var e=assertThrows(CdSpring.UnsupportedSpring.class,h::walk);assertEquals(CdSpring.UnsupportedBoundary.PARENT_READ,e.boundary());assertEquals(0xFFD809,e.readAddress24().orElseThrow());assertEquals(s,h.placement.pool().state(32));}}
 @Test void plainNativeDeleteHappensAfterDrawAndKeepsAllPlacementSavedBytes()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){seed(h,32,2,0);h.placement.pool().write(h.placement.pool().state(32).moveWord(SPRING_ANCHOR_X,0x1000));var before=h.placement.capture();h.walk();assertEquals(0,h.placement.pool().state(32).id());nonwrites(h,before,Set.of(32));h.finish();}}
 @Test void mirrorRoutineFiveUsesTheActualPrimaryAndSkipsParentAndCameraReads()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){var s=seed(h,32,0,0).moveByte(ROUTINE_2,5).moveWord(SPRING_PARENT,0xD801).moveWord(SPRING_ANCHOR_X,0xFFFF);h.placement.pool().write(s);h.walk();var out=h.placement.pool().state(32);assertEquals(h.frame.state().motion().centreX16_16()>>>16,out.centreX());assertEquals(h.frame.state().motion().centreY16_16()>>>16,out.centreY());assertEquals(2,out.routine());assertEquals(0x8520,out.word(TILE));h.finish();}}
 @Test void nativeSolidAndLaunchUseOriginalFramePreparationsBeforeExistingSound()throws Exception{try(var h=TestSonicCdR31aSpringReviewControls.present(0,0)){var s=seed(h,32,2,0).moveByte(SPRITE_FLAGS,0x84).moveWord(X,96).moveWord(Y,1031).moveWord(SPRING_SPEED,0xF000).moveByte(WIDTH,16).moveByte(Y_RADIUS,8);h.placement.pool().write(s);var before=h.frame.state();var bank=h.placement.capture();h.walk();assertEquals(4,h.placement.pool().state(32).routine(),"Literal constructed contact precondition; never fit production");assertEquals(-0x1000,h.frame.state().motion().yVelocity());assertEquals(0x10,h.frame.state().motion().animation());assertEquals((before.motion().centreY16_16()>>>16)+8,h.frame.state().motion().centreY16_16()>>>16);assertEquals(1,h.cut.sounds().size());assertInstanceOf(SonicCdGameModule.PastSpringFm.class,h.cut.sounds().getFirst());nonwrites(h,bank,Set.of(32));h.finish();}}
 @Test void realReadReceiptsRejectForeignThreadRepeatedAndExpiredCallsWithoutClosingHealthyFrame()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){seed(h,32,0,0);var b=(CdSpring)field(h.pass,"spring");var ports=(CdSpring.LivePorts)field(b,"livePorts");var held=new AtomicReference<CdSpring.OriginalCall>();set(b,"livePorts",new Forward(ports){public int read(CdSpring.OriginalCall c){held.set(c);assertThrows(IllegalStateException.class,()->h.pass.runWalk(7));assertFalse(h.frame.closed());var e=new AtomicReference<Throwable>();var t=new Thread(()->{try{ports.read(c);}catch(Throwable x){e.set(x);}});t.start();try{t.join(5000);}catch(InterruptedException x){throw new AssertionError(x);}assertFalse(t.isAlive());assertInstanceOf(IllegalStateException.class,e.get());int n=ports.read(c);assertThrows(IllegalStateException.class,()->ports.read(c));return n;}});h.walk();assertFalse(b.isCurrentCall(held.get()));assertThrows(IllegalStateException.class,()->ports.read(held.get()));h.finish();}}
 @Test void omittedDrawAndObserverCannotTurnEqualValuesIntoNativeReceipts()throws Exception{
  try(var h=new TestSonicCdR31aObjectPass.Harness()){seed(h,32,0,0);var b=(CdSpring)field(h.pass,"spring");var p=(CdSpring.LivePorts)field(b,"livePorts");set(b,"livePorts",new Forward(p){public void draw(CdSpring.OriginalCall c){}});assertThrows(IllegalStateException.class,h::walk);}
  try(var h=new TestSonicCdR31aObjectPass.Harness()){var s=seed(h,32,0,0);var b=(CdSpring)field(h.pass,"spring");set(b,"observer",new CdSpring.NativeObserver(){public void before(CdSpring.OriginalCall c){}public void after(CdSpring.OriginalCall c){}});assertThrows(IllegalStateException.class,h::walk);assertSame(s,h.placement.pool().state(32));}}
 @Test void originalDrawErrorKeepsTheNativePrefixAndRetiresEveryScope()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){seed(h,32,0,0);var b=(CdSpring)field(h.pass,"spring");var p=(CdSpring.LivePorts)field(b,"livePorts");var e=new AssertionError("after original Draw");set(b,"livePorts",new Forward(p){public void draw(CdSpring.OriginalCall c){p.draw(c);throw e;}});assertSame(e,assertThrows(AssertionError.class,h::walk));assertEquals(2,h.placement.pool().state(32).routine());assertNull(field(h.pass,"springInvocation"));}}
 @Test void dirtyBlockChildRunsOnlyAtItsReachedLaterPhysicalVisit()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){var p=h.placement.pool();p.write(p.state(32).moveByte(ID,0x21).moveByte(SUBTYPE,2).moveWord(X,100).moveWord(Y,100));var tail=p.state(33).moveWord(X_FRACTION,0xCAFE).moveByte(SUBTYPE2,77);p.write(tail);h.walk();assertEquals(0x0A,p.state(33).id());assertEquals(2,p.state(33).routine());assertEquals(0x20968A,p.state(33).longBits(MAPPINGS));assertEquals(0xCAFE,p.state(33).word(X_FRACTION));assertEquals(77,p.state(33).unsignedByte(SUBTYPE2));h.finish();}}
 @Test void oldAndFullPoolControlsNeverInventAnAllocationInsideSpring()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){seed(h,40,0,0);var earlier=h.placement.pool().state(32);h.walk();assertSame(earlier,h.placement.pool().state(32));h.finish();}try(var h=new TestSonicCdR31aObjectPass.Harness()){for(int n=32;n<128;n++)seed(h,n,2,0);var bank=h.placement.capture();h.walk();nonwrites(h,bank,Set.of());h.finish();}}
 @Test void deferredInvalidFrameStopsAtExistingMapperAfterCompletedBodyAndDraw()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){seed(h,32,2,0);h.placement.pool().write(h.placement.pool().state(32).moveByte(MAP_FRAME,3));h.walk();assertThrows(UnsupportedOperationException.class,h::finish);}}
 @Test void sharedAnimationKeepsTheTimerPrefixAtItsFirstMissingDirectory()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){var source=seed(h,32,4,0).moveByte(SPRITE_FLAGS,0x84).moveByte(ANIMATION,255).moveByte(PREVIOUS_ANIMATION,255).moveByte(ANIMATION_TIME,0);h.placement.pool().write(source);var e=assertThrows(CdObjectAnimation.SelectedReadFailure.class,h::walk);assertEquals(CdObjectAnimation.Kind.DIRECTORY,e.boundary());assertEquals(255,h.placement.pool().state(32).unsignedByte(ANIMATION_TIME));assertNull(field(h.pass,"springInvocation"));}}
 @Test void equalPublicLaunchValuesDoNotReplaceTheOriginalProducerPayload()throws Exception{try(var h=TestSonicCdR31aSpringReviewControls.present(0,0)){seed(h,32,2,0);h.placement.pool().write(h.placement.pool().state(32).moveByte(SPRITE_FLAGS,0x84).moveWord(X,96).moveWord(Y,1031).moveWord(SPRING_SPEED,0xF000).moveByte(WIDTH,16).moveByte(Y_RADIUS,8));var b=(CdSpring)field(h.pass,"spring");var ports=(CdSpring.LivePorts)field(b,"livePorts");var reached=new boolean[1];set(b,"livePorts",new Forward(ports){public void launch(CdSpring.OriginalCall c,CdSpring.LaunchCall l){reached[0]=true;var clone=new CdSpring.LaunchCall(l.identity(),l.expectedPlayer(),l.expectedGlobals(),l.finalPlayer(),l.finalGlobals(),l.playerWrites(),l.globalWrites());assertThrows(IllegalStateException.class,()->ports.launch(c,clone));ports.launch(c,l);}});h.walk();assertTrue(reached[0],"Literal source contact must actually reach launch");assertEquals(4,h.placement.pool().state(32).routine());assertEquals(1,h.cut.sounds().size());assertFalse(h.frame.closed());h.finish();}}
 @Test void unownedFrameAndBankWritesKeepTheOriginalErrorAndDistinctVerificationFaults()throws Exception{
  for(boolean bank:new boolean[]{false,true})try(var h=new TestSonicCdR31aObjectPass.Harness()){seed(h,32,0,0);var b=(CdSpring)field(h.pass,"spring");var original=(CdSpring.NativeObserver)field(b,"observer");var e=new AssertionError("Spring foreign prefix");set(b,"observer",new CdSpring.NativeObserver(){public void before(CdSpring.OriginalCall c){original.before(c);if(bank)h.placement.bsetSavedFlag(200,2,CdObjectPlacementRuntime.SavedBit.LOADED);else h.frame.applyPreparedObjectSolidPublication(h.frame.prepareObjectPrimaryAngle(h.frame.environment().movement().globals().primaryAngle(),7));throw e;}public void after(CdSpring.OriginalCall c){original.after(c);}});assertSame(e,assertThrows(AssertionError.class,h::walk));assertTrue(e.getSuppressed().length>0);for(var f:e.getSuppressed())assertNotSame(e,f);assertNull(field(h.pass,"springInvocation"));}}
 static CdObjectState seed(TestSonicCdR31aObjectPass.Harness h,int whole,int routine,int subtype){var s=h.placement.pool().state(whole).moveByte(ID,0x0A).moveByte(ROUTINE,routine).moveByte(SUBTYPE,subtype).moveByte(SPRITE_FLAGS,4).moveLong(MAPPINGS,0x20968A).moveWord(X,100).moveWord(Y,100).moveWord(SPRING_ANCHOR_X,100);h.placement.pool().write(s);return s;}
 private static CdObjectState init(CdObjectState s,int routine,int tile,int map,int width,int radius){return s.moveByte(ROUTINE,routine).moveLong(MAPPINGS,map).moveWord(TILE,tile).moveByte(SPRITE_FLAGS,s.spriteFlags()|4).moveByte(WIDTH,width).moveByte(Y_RADIUS,radius).moveWord(SPRING_ANCHOR_X,s.centreX()).moveByte(PRIORITY,4).moveWord(SPRING_SPEED,(s.subtype()&2)==0?0xF000:0xF600);}
 private static void nonwrites(TestSonicCdR31aObjectPass.Harness h,CdObjectPlacementRuntime.Snapshot b,Set<Integer> changed){var n=h.placement.capture();assertEquals(b.status(),n.status());assertArrayEquals(b.savedFlags().copy(),n.savedFlags().copy());for(int w=32;w<128;w++)if(!changed.contains(w))assertEquals(b.pool().slots().get(w-32),h.placement.pool().state(w));}
 private static Object field(Object o,String n)throws Exception{var f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}private static void set(Object o,String n,Object v)throws Exception{var f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}
 private static String sha(CdAssetBytes b)throws Exception{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(b.copy()));}
 private static class Forward implements CdSpring.LivePorts{final CdSpring.LivePorts p;Forward(CdSpring.LivePorts p){this.p=p;}public void checkSolid(CdSpring.OriginalCall c,CdSolidObject.Entry e){p.checkSolid(c,e);}public int read(CdSpring.OriginalCall c){return p.read(c);}public void solid(CdSpring.OriginalCall c,CdSpring.PrefixSolidCall s){p.solid(c,s);}public void launch(CdSpring.OriginalCall c,CdSpring.LaunchCall l){p.launch(c,l);}public void draw(CdSpring.OriginalCall c){p.draw(c);}public void sound(CdSpring.OriginalCall c,CdSpring.FmSound s){p.sound(c,s);}}
}
